style.css:
/* Beabadoobee Dreamy Aesthetic Theme for Clever */

/* Background image */
body {
  background: url("https://i.pinimg.com/736x/6c/69/e5/6c69e5f8be0ab275bcc10c56cb69853f.jpg") no-repeat center center fixed !important;
  background-size: cover !important;
  color: #f0f0ff !important;
  font-family: "Poppins", sans-serif !important;
  text-shadow: 0 0 6px rgba(200, 200, 255, 0.8);
}

/* Light overlay for readability */
body > * {
  background-color: rgba(0, 0, 0, 0.1) !important; /* very light overlay */
}

/* Buttons & input fields with soft neon glow */
button,
input,
select,
textarea {
  background: rgba(60, 60, 100, 0.6) !important;
  border-radius: 10px !important;
  border: 1px solid rgba(200, 200, 255, 0.3) !important;
  color: #f0f0ff !important;
  box-shadow: 0 0 6px rgba(200, 200, 255, 0.5);
  transition: all 0.3s ease-in-out !important;
}

/* Hover effect with neon pop */
button:hover,
input:hover,
select:hover,
textarea:hover {
  background: rgba(100, 100, 200, 0.8) !important;
  box-shadow: 0 0 12px rgba(200, 200, 255, 0.8) !important;
}

/* Links and headings glow softly */
a, h1, h2, h3, p, span, div {
  text-shadow: 0 0 6px rgba(200, 200, 255, 0.7);
}
